package com.dappunq.persistence;
import com.dappunq.model.valuation.*; import jakarta.persistence.*; import java.math.*; import java.time.*;
@Entity @Table(name="valuaciones",uniqueConstraints=@UniqueConstraint(columnNames={"usuario_id","jugador_id","ventana_dominical"})) public class ValuationEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) @JoinColumn(name="usuario_id") UserEntity user; @ManyToOne(optional=false) @JoinColumn(name="jugador_id") PlayerEntity player; @Column(name="ventana_dominical") String ventana; @Enumerated(EnumType.STRING) StrategyType estrategia; @Enumerated(EnumType.STRING) ValuationStatus estado; @Column(name="valor_unitario") BigDecimal valorUnitario; @Column(name="creado_en") Instant creadoEn=Instant.now(); protected ValuationEntity(){} public ValuationEntity(UserEntity u,PlayerEntity p,String w,StrategyType s,BigDecimal v){user=u;player=p;ventana=w;estrategia=s;valorUnitario=v;estado=ValuationStatus.VALUADA;} }
